mapper.select:
SELECT 

FROM swm_hidden_danger a




		AND a.danger_name LIKE #{dangerName}


		AND a.location LIKE #{location}


		AND a.inspection_plan_id = #{inspectionPlanId}


		AND a.is_beacon_deployed = #{isBeaconDeployed}


		AND a.is_handled = #{isHandled}


		AND a.status = #{status}


ORDER BY a.create_date DESC
